def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 4:
        return 'C'
    if n == 4:
        return 'D'
    if n == 5:
        return 'C'

    my_d = 0
    opp_c_after_my_d = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            my_d += 1
            if history[i + 1][1] == 'C':
                opp_c_after_my_d += 1

    opp_d = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_d += 1

    forgiveness = opp_c_after_my_d / max(1, my_d)
    opp_rate = opp_d / n

    if opp_rate > 0.5:
        p = 0.9
    elif opp_rate > 0.3:
        p = 0.6
    elif forgiveness > 0.8:
        p = 0.33
    elif forgiveness > 0.6:
        p = 0.25
    elif forgiveness > 0.4:
        p = 0.15
    elif forgiveness > 0.2:
        p = 0.05
    else:
        p = 0.02

    if history[-1][1] == 'D':
        recent_d = 0
        start = max(0, n - 5)
        for i in range(start, n):
            if history[i][1] == 'D':
                recent_d += 1
        if opp_rate > 0.3 or recent_d >= 2:
            return 'D'
        return 'C' if rng.random() < 0.7 else 'D'

    if rng.random() < p:
        return 'D'
    return 'C'
